function updateAutoBackupInfo(){const el=document.getElementById('autoBackupInfo');if(!el)return;try{const raw=TFStorage.read(AUTO_BACKUP_KEY);if(!raw){el.textContent='暂无自动备份';el.style.color='var(--text-light)';return;}
const obj=JSON.parse(raw);if(obj&&obj.time){const d=new Date(obj.time);const timeStr=d.getFullYear()+'-'+
String(d.getMonth()+1).padStart(2,'0')+'-'+
String(d.getDate()).padStart(2,'0')+' '+
String(d.getHours()).padStart(2,'0')+':'+
String(d.getMinutes()).padStart(2,'0');el.textContent='最近备份：'+timeStr+(obj.note?' · '+obj.note:'');el.style.color='var(--green)';}else{el.textContent='有自动备份可恢复';el.style.color='var(--green)';}}catch(e){el.textContent='暂无自动备份';el.style.color='var(--text-light)';}}
function restoreAutoBackup(){let raw=null;try{raw=TFStorage.read(AUTO_BACKUP_KEY);}catch(e){if(window.__silent)window.__silent(e,'01b:restoreAutoBackup');}
if(!raw){showToast('没有可恢复的自动备份');return;}
let obj=null;try{obj=JSON.parse(raw);}catch(e){showToast('自动备份已损坏，无法恢复');return;}
const data=obj&&obj.data?obj.data:obj;if(!isValidBackup(data)){const _r=validateBackup(data);showToast('自动备份数据异常，无法恢复：'+(_r.reason||'结构不符'));return;}
const timeStr=obj&&obj.time?'（'+String(obj.time).slice(0,16).replace('T',' ')+'）':'';const _restoreMsg='确定用自动备份'+timeStr+'覆盖当前数据吗？\n当前数据会先再备份一次，仍可找回。';const _doRestore=function(){_autoBackupGuard('恢复自动备份').then(function(ok){if(!ok)return;applyBackupData(data,'✅ 已恢复自动备份'+timeStr);});};if(typeof window.rsAsk==='function')window.rsAsk(_restoreMsg,{title:'恢复自动备份',okText:'恢复'},_doRestore);else if(confirm(_restoreMsg))_doRestore();}
function importData(event){const file=event.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=e=>{try{const parsed=JSON.parse(e.target.result);const _vb=validateBackup(parsed);if(!_vb.ok){const _failMsg='导入失败：\n\n'+_vb.reason;if(typeof window.rsAlert==='function')window.rsAlert(_failMsg,{title:'导入失败',okText:'知道了'});else if(typeof window.rsInfo==='function')window.rsInfo(_failMsg,{title:'导入失败'});else showToast('导入失败：'+_vb.reason);event.target.value='';return;}
if(_vb.warns&&_vb.warns.length){try{console.warn('[导入] 旧格式兼容提示：',_vb.warns);if(window.__errRep)window.__errRep.warn('import',_vb.warns.join('；'));}catch(e2){if(window.__silent)window.__silent(e2,'01b:importData');}}
const versionInfo=parsed.exportDate?'（备份日期 '+parsed.exportDate+'）':'';const _importMsg='导入'+versionInfo+'将覆盖当前所有数据，确定继续吗？\n（导入前数据会自动备份，可恢复）';const _doImport=function(){_autoBackupGuard('导入数据').then(function(ok){if(!ok)return;applyBackupData(parsed,'✅ 数据已导入'+versionInfo+'，导入前数据已自动备份');});};if(typeof window.rsAsk==='function')window.rsAsk(_importMsg,{title:'导入数据',okText:'继续导入'},_doImport);else if(confirm(_importMsg))_doImport();}catch(err){showToast('导入失败：文件格式错误');}
event.target.value='';};reader.readAsText(file);}
