const INTERRUPT_CATEGORIES=[{key:'phone',label:'📱 刷手机',keys:['刷手机','看手机','手机','刷','抖音','短视频','微博','小红书','淘宝','视频','游戏','小说']},{key:'msg',label:'💬 回消息',keys:['回消息','消息','微信','qq','信息','回复','回信','电话','来电','接电话','邮件']},{key:'people',label:'👥 别人找我',keys:['别人找我','别人','找我','同事','老板','家人','妈妈','爸爸','老婆','老公','孩子','客户','领导','同学']},{key:'notice',label:'🔔 通知打扰',keys:['通知','提醒','弹窗','推送','铃声','叮']},{key:'toilet',label:'🚽 上厕所',keys:['上厕所','厕所','洗手间','尿急','小便','大便','拉','尿']},{key:'drink',label:'💧 喝水',keys:['喝水','倒水','水杯','口渴']},{key:'food',label:'🍚 吃东西',keys:['吃东西','吃','饭','零食','水果','泡面','外卖','下午茶','点心']},{key:'distract',label:'💭 走神发呆',keys:['走神','发呆','想','神游','分心','思绪']},{key:'tired',label:'😴 困了休息',keys:['困','累','睡','休息','闭眼','眯']},{key:'house',label:'🏠 家务琐事',keys:['家务','扫地','洗碗','快递','取快递','收衣服','做饭','晾']},{key:'work',label:'💼 临时事务',keys:['工作','开会','会议','处理','切换','临时','急事','任务','事务']}];function categorizeInterrupt(reason){const r=(reason||'').trim();if(!r)return'📝 其他';for(let i=0;i<INTERRUPT_CATEGORIES.length;i++){const c=INTERRUPT_CATEGORIES[i];if(r===c.label||r.indexOf(c.label.slice(2))>=0)return c.label;}
for(let i=0;i<INTERRUPT_CATEGORIES.length;i++){const c=INTERRUPT_CATEGORIES[i];for(let j=0;j<c.keys.length;j++){if(r.indexOf(c.keys[j])>=0)return c.label;}}
return'📝 其他';}
