function getPrevWeekStartStr(weekStartStr){const base=weekStartStr||getWeekStartStr();const d=new Date(base+'T00:00:00');d.setDate(d.getDate()-7);return getDateStr(d);}
function getWeekHeldTomatoes(){const extra=(appData.rankSystem&&appData.rankSystem.extraWeekTomatoes)||0;const shopSpent=(appData.tree&&appData.tree.weekTomatoSpent)||0;return Math.max(0,countWeekTomatoes(getWeekStartStr())-shopSpent+extra);}
function badgesAtRiskBySpend(spendQty){if(!spendQty||spendQty<=0)return[];const held=getWeekHeldTomatoes();const after=Math.max(0,held-spendQty);const out=[];WEEKLY_BADGES.forEach(function(b){if(getBadgeState(b)!=='this')return;if(held>=b.goal&&after<b.goal)out.push(b);});return out;}
