function parseRankDelta(m){if(m.indexOf('段位晋级')>=0)return 1;if(m.indexOf('不掉星')>=0||m.indexOf('不会掉星')>=0)return 0;const dm=m.match(/降星\s*(\d+)/)||m.match(/-\s*(\d+)\s*⭐/);if(dm)return-parseInt(dm[1]);const px=m.match(/额外\s*[+]?(\d+)\s*⭐/);if(px)return parseInt(px[1]);const pm=m.match(/(?:上星|连胜|赌注赢了)[^+\d]*[+]?(\d+)/);if(pm)return parseInt(pm[1]);const pm2=m.match(/[+](\d+)/);if(pm2&&m.indexOf('星')>=0)return parseInt(pm2[1]);return 0;}
