function toggleMustDo(id){const today=getTodayStr();const list=appData.mustDos[today]||[];const it=list.filter(function(x){return idEq(x.id,id);})[0];if(!it)return;it.done=!it.done;saveData();renderMustDoSection();renderPlanMustRows();const allDone=list.length&&list.every(function(x){return x.done;});if(allDone&&!appData.mustDoRewarded[today]){playSound('habitDone');showToast('🎉 今日必做 3 件事全部完成！去「🎯 目标」页点「领取 +'+COIN_MUSTDO_REWARD+'🪙」吧');}}
