const COIN_EX_RATE=6;const COIN_EX_WEEK_MAX=120;function getWeekCoinExchanged(){const ws=getWeekStartStr();const tr=appData.tree;if(!tr)return 0;if(tr.weekCoinExchangedWeek!==ws){tr.weekCoinExchanged=0;tr.weekCoinExchangedWeek=ws;}
const v=tr.weekCoinExchanged||0;return Math.min(v,COIN_EX_WEEK_MAX);}
function getExchangeAvail(){return Math.max(0,getWeekTomatoPoints()-countWeekAllSpent()+(appData.rankSystem.extraWeekTomatoes||0));}
function doCoinExchange(n){const tr=appData.tree;if(!tr)return;getWeekCoinExchanged();const avail=Math.floor(getExchangeAvail());const used=getWeekCoinExchanged();const canTrade=Math.min(avail,Math.floor(Math.max(0,COIN_EX_WEEK_MAX-used)/COIN_EX_RATE));if(canTrade<=0){const extra=(appData.rankSystem&&appData.rankSystem.extraWeekTomatoes)||0;let msg;if(used>=COIN_EX_WEEK_MAX){msg='🪙 本周兑换额度已用完（已兑 '+used+'/'+COIN_EX_WEEK_MAX+' 🪙），下周一重置';}else if(avail<=0){msg=getWeekTomatoPoints()>0||extra>0?'🍅 番茄已经用完了（本周可消耗 0 个）——再完成几个完整🍅就能继续兑换':'🍅 本周还没有可消耗的番茄——先完成几个完整🍅再来兑换';}else{msg='🪙 剩余额度只剩 '+(COIN_EX_WEEK_MAX-used)+' 🪙，不足一份（'+COIN_EX_RATE+' 🪙），下周再来';}
showToast(msg);closeModal('coinExchangeModal');return;}
let qty=n;if(qty<0)qty=canTrade;qty=Math.max(1,Math.min(qty,canTrade));const _lost=badgesAtRiskBySpend(qty);const coins=qty*COIN_EX_RATE;resetWeekTomatoSpentIfNeeded();tr.weekTomatoSpent=(tr.weekTomatoSpent||0)+qty;tr.weekCoinExchanged=used+coins;coinEarn(coins,'exchange',qty+' 个周番茄兑换');saveData();showToast('🔄 已兑换 '+qty+' 个周番茄 → '+coins+' 🪙（统计与海报不受影响）');if(_lost.length)
showToast('⚠️ '+
_lost.map(function(b){return b.icon+b.name;}).join('、')+' 因番茄消耗已熄灭（再完成几个🍅 可重新点亮）');closeModal('coinExchangeModal');if(window.store&&window.store.emit){try{window.store.emit('tree.coins');}catch(e){if(window.__silent)window.__silent(e,'01d3:doCoinExchange');}}else{renderTreeShop();renderTreeSection();renderWeeklyBadges();renderRankSystem();renderStats();}}
const COIN_LOG_MAX=500;function coinLedgerEnsure(){const tr=appData&&appData.tree;if(!tr)return[];if(!Array.isArray(tr.coinLog))tr.coinLog=[];return tr.coinLog;}
function coinLedgerInit(){const tr=appData&&appData.tree;if(!tr)return[];const log=coinLedgerEnsure();if(tr.coinLogInit)return log;tr.coinLogInit=true;const diff=coinLedgerDiff(log,tr.coins);if(diff!==0){const first=log[0];log.unshift(coinTxMake({type:'opening',amount:diff,after:diff,at:first?Number(first.at)-1:Date.now(),reason:'期初结转（记账功能上线时的余额）'}));}
return log;}
function coinLedgerPush(tx){const log=coinLedgerEnsure();log.push(tx);if(log.length>COIN_LOG_MAX)coinLedgerCompact();return tx;}
function coinLedgerCompact(){const log=appData.tree&&appData.tree.coinLog;if(!Array.isArray(log)||log.length<=COIN_LOG_MAX)return;const keep=COIN_LOG_MAX-1;const cutCount=log.length-keep;const cut=log.slice(0,cutCount);const last=cut[cut.length-1];const carried=coinTxMake({type:'opening',amount:coinLedgerSum(cut),after:last.after,at:last.at,reason:'结转（更早 '+cutCount+' 笔已合并）'});appData.tree.coinLog=[carried].concat(log.slice(cutCount));}
function coinEarn(amount,type,reason,meta){const n=Math.round(Number(amount)||0);if(!appData||!appData.tree||n<=0)return null;coinLedgerInit();appData.tree.coins=(Number(appData.tree.coins)||0)+n;return coinLedgerPush(coinTxMake({type:type,amount:n,reason:reason,meta:meta,after:appData.tree.coins}));}
function coinSpend(amount,type,reason,meta){const n=Math.round(Number(amount)||0);if(!appData||!appData.tree||n<=0)return false;coinLedgerInit();if((Number(appData.tree.coins)||0)<n)return false;appData.tree.coins=(Number(appData.tree.coins)||0)-n;coinLedgerPush(coinTxMake({type:type,amount:-n,reason:reason,meta:meta,after:appData.tree.coins}));return true;}
function coinUndo(txId){const log=coinLedgerInit();const id=String(txId);if(!coinTxUndoable(log,id))return false;const hit=log.filter(function(t){return String(t.id)===id;})[0];if(!hit)return false;const back=-hit.amount;if(back<0&&(Number(appData.tree.coins)||0)<Math.abs(back))return false;appData.tree.coins=(Number(appData.tree.coins)||0)+back;coinLedgerPush(coinTxMake({type:'undo',amount:back,after:appData.tree.coins,undoOf:id,reason:'撤销：'+(hit.reason||coinTxTypeLabel(hit.type)),meta:{undoneType:hit.type}}));saveData();return true;}
function coinLedgerCheck(){const log=coinLedgerInit();const balance=Number((appData.tree&&appData.tree.coins)||0);return{sum:coinLedgerSum(log),balance:balance,diff:coinLedgerDiff(log,balance)};}
function coinLedgerRebalance(){const r=coinLedgerCheck();if(r.diff===0)return r;coinLedgerPush(coinTxMake({type:'migrate',amount:r.diff,after:r.balance,reason:'对账修正（补记差额）'}));return coinLedgerCheck();}
let ITEM_DEFS={waterProtect:{name:'连续浇水保护卡',icon:'💧',price:350,currency:'coin',desc:'使用后，明天不浇水也不断连续浇水天数',type:'protect'},streakProtect:{name:'连续天数保护卡',icon:'🔥',price:18,currency:'week',desc:'使用后，明天不完成番茄也不断连续天数',type:'protect'},waterRecover:{name:'浇水恢复卡',icon:'♻️',price:500,currency:'coin',desc:'断掉后3天内使用，恢复连续浇水天数',type:'recover'},streakRecover:{name:'连续天数恢复卡',icon:'🔄',price:30,currency:'week',desc:'断掉后3天内使用，恢复连续专注天数',type:'recover'},renameCard:{name:'改名卡',icon:'✏️',price:300,currency:'coin',desc:'修改树的名字，每张可改一次（改名时自动消耗）',type:'rename'},reviveStone:{name:'复活石',icon:'🪄',price:600,currency:'coin',desc:'枯死的树使用后原地复活（一次性；树没枯死不可用，可提前囤）',type:'revive'}};function buyItem(id){resetWeekTomatoSpentIfNeeded();let tr=appData.tree;let def=ITEM_DEFS[id];if(def.type==='protect'){let _ak=id==='waterProtect'?'activeWaterProtect':'activeStreakProtect';let _held=(tr.inventory[id]||0)+(tr[_ak]?1:0);if(_held>=2){showToast('🛡️ '+def.name+'已达持有上限（2 张），用掉一张才能再买');return;}}
if(def.currency==='coin'){const _realPrice=getDynamicPrice(def.price,tr.coins||0);if((tr.coins||0)<_realPrice){showToast('🪙 果实币不足（需 '+_realPrice+'）');return;}
coinSpend(_realPrice,'prop','道具卡：'+def.name);}else{let avail=getExchangeAvail();if(avail<def.price){showToast('🍅 本周可用番茄不足（需 '+def.price+'，当前 '+Math.floor(avail)+'）');return;}
tr.weekTomatoSpent=(tr.weekTomatoSpent||0)+def.price;}
tr.inventory[id]=(tr.inventory[id]||0)+1;saveData();renderTreeShop();showToast('✅ 已购买 '+def.name+'！已存入库存，点击"使用"才生效');}
function useItem(id){let tr=appData.tree;let def=ITEM_DEFS[id];if((tr.inventory[id]||0)<=0){showToast('库存不足');return;}
if(def.type==='rename'){openTreeNameModal();return;}
if(def.type==='revive'){if(!appData.tree.dead){showToast('🌳 树没有枯死，用不到复活石');return;}
appData.tree.dead=false;appData.tree.deadDate=null;const _revivePts=reviveDegradePoints(appData.tree.peakPoints||0);appData.tree.points=_revivePts;appData.tree.lastActiveDate=getTodayStr();appData.tree.species='tomato';appData.tree.speciesPoints={tomato:_revivePts};appData.tree.plantedSpecies=['tomato'];appData.tree.speciesLastActive={};appData.tree.reviveProtectUntil=addDaysStr(getTodayStr(),7);appData.tree.inventory[id]=(appData.tree.inventory[id]||0)-1;saveData();renderTreeShop();renderTreeSection();renderTimerTree();const _rs=getTreeStage(_revivePts);showToast('🪄 复活石生效！树复活到「'+_rs.emoji+' '+_rs.name+'」阶段');return;}
let tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);let tds=getDateStr(tomorrow);if(def.type==='protect'){let activeKey=id==='waterProtect'?'activeWaterProtect':'activeStreakProtect';let protType=id==='waterProtect'?'water':'streak';if(tr[activeKey]===tds){showToast('明天已经在保护中了');return;}
tr[activeKey]=tds;addProtectedDate(protType,tds);tr.inventory[id]--;showToast('🛡️ '+def.name+'已激活！明天('+tds+')受保护');}else{let hist=tr.streakHistory||[];if(!hist.length){showToast('暂无历史记录可恢复');return;}
if(id==='waterRecover'){let maxWS=0;hist.forEach(function(h){if(h.waterStreak>maxWS)maxWS=h.waterStreak;});if(maxWS<=0){showToast('没有可恢复的浇水连续记录');return;}
tr.waterStreak=maxWS;let y=new Date();y.setDate(y.getDate()-1);tr.lastWaterDate=getDateStr(y);tr.usedWaterRecoveries=(tr.usedWaterRecoveries||0)+1;showToast('✅ 浇水连续已恢复为 '+maxWS+' 天！');}else{let maxStreak=0;hist.forEach(function(h){if(h.streak>maxStreak)maxStreak=h.streak;});if(maxStreak<=0){showToast('没有可恢复的连续天数记录');return;}
for(let i=1;i<=maxStreak;i++){let dd=new Date();dd.setDate(dd.getDate()-i);addProtectedDate('streak',getDateStr(dd));}
tr.usedStreakRecoveries=(tr.usedStreakRecoveries||0)+1;showToast('✅ 连续天数已恢复为 '+maxStreak+' 天！');}
tr.inventory[id]--;}
saveData();renderTreeShop();renderTreeSection();renderStats();}
function cancelProtection(id){let tr=appData.tree;let activeKey=id==='waterProtect'?'activeWaterProtect':'activeStreakProtect';let protType=id==='waterProtect'?'water':'streak';let ds=tr[activeKey];if(!ds){showToast('当前没有激活的保护');return;}
if(ds===true){tr[activeKey]=null;tr.inventory[id]=(tr.inventory[id]||0)+1;saveData();renderTreeShop();renderTreeSection();renderStats();showToast('🛡️ 已取消保护待命，道具退回库存');return;}
let today=getTodayStr();if(ds<=today){showToast('保护日已到/已过，道具已生效使用，无法取消退回');return;}
let key=protType==='water'?'waterProtectedDates':'streakProtectedDates';if(tr[key]){let idx=tr[key].indexOf(ds);if(idx>=0)tr[key].splice(idx,1);}
tr[activeKey]=null;tr.inventory[id]=(tr.inventory[id]||0)+1;saveData();renderTreeShop();renderTreeSection();renderStats();showToast('已取消保护，道具已退回库存');}
function getTreeMood(){const today=new Date();today.setHours(0,0,0,0);const tr=appData.tree;const lastActive=tr.lastActiveDate?Math.floor((today-new Date(tr.lastActiveDate+'T00:00:00'))/DAY_MS):999;const lastWater=tr.lastWaterDate?Math.floor((today-new Date(tr.lastWaterDate+'T00:00:00'))/DAY_MS):999;const days=Math.max(lastActive,lastWater);if(days<=1)return{emoji:'😊',label:'精神饱满',fade:0};if(days<=2)return{emoji:'🙂',label:'有点蔫',fade:0.35};if(days<=4)return{emoji:'😟',label:'想你了',fade:0.6};return{emoji:'😢',label:'快枯萎了',fade:0.85};}
