const TREE_FORTUNE=[{id:'great',icon:'🍀',name:'大吉',desc:'今日树成长 +8%，树会开心开花',buff:{growth:1.08}},{id:'good',icon:'🌸',name:'中吉',desc:'今日首次触碰树金币翻倍（+10）',buff:{touch:10}},{id:'small',icon:'🌿',name:'小吉',desc:'今日浇水多算 1 天露珠进度',buff:{dew:1}},{id:'normal',icon:'📜',name:'平',desc:'平平淡淡才是真，树说句鼓励的话',buff:{}},{id:'bad',icon:'🌧️',name:'凶',desc:'今日树成长 -5%，树会多吐槽你',buff:{growth:0.95}},{id:'dread',icon:'💀',name:'大凶',desc:'今日树成长 -8%，开启毒舌模式',buff:{growth:0.92,dark:true}}];const TREE_FORTUNE_WEIGHTS=[8,16,20,30,18,8];const TREE_DARK_TALKS=['今日大凶：本树拒绝营业，先去完成番茄再说！','凶兆已至：你再偷懒，天都要塌啦（假的）','今天我不哄你了，自己看着办吧😤','毒舌模式：主人，你的树觉得你还能再努努力','大凶预警：小心点，别被自己的拖延绊倒','本树掐指一算：你今天又会摸鱼，准没跑'];function getFortune(){const tr=appData.tree;if(!tr.fortuneToday)return null;if(tr.fortuneToday.date!==getTodayStr()){tr.fortuneToday=null;if(tr.dailyGrowBoost&&tr.dailyGrowBoost!==1)tr.dailyGrowBoost=1;return null;}
return(TREE_FORTUNE.find(function(f){return f.id===tr.fortuneToday.id;})||null);}
function drawFortune(){const tr=appData.tree;if((tr.fortuneCount||0)>=1){showToast('🎴 今天已经抽过运势签啦，明天再来');return;}
const _fCost=getDynamicPrice(20,tr.coins||0);if((tr.coins||0)<_fCost){showToast('🪙 果实币不足（需 '+_fCost+'）');return;}
coinSpend(_fCost,'shop','抽运势签');tr.fortuneCount=(tr.fortuneCount||0)+1;const total=TREE_FORTUNE_WEIGHTS.reduce(function(s,w){return s+w;},0);let r=Math.floor(Math.random()*total);let idx=0;for(let i=0;i<TREE_FORTUNE_WEIGHTS.length;i++){r-=TREE_FORTUNE_WEIGHTS[i];if(r<0){idx=i;break;}}
const f=TREE_FORTUNE[idx];tr.fortuneToday={date:getTodayStr(),id:f.id};saveData();const today=getTodayStr();if(f.id==='good'&&tr.lastTouchBonusDate===today){coinEarn(5,'fortune','中吉补偿：今日已摸过树，补发翻倍差额');showToast('🌸 中吉：你今天已经摸过树啦，直接补你 5🪙（翻倍那部分）');}else if(f.id==='small'&&tr.lastWaterDate===today){tr.waterStreak=(tr.waterStreak||0)+1;showToast('🌿 小吉：你今天已经浇过水啦，直接加 1 天露珠进度');}else{showToast('🎴 抽到：'+f.icon+' '+f.name);}
saveData();renderTreeShop();renderTreeSection();}
