function getRecommendedWorkDuration(){const DAYS=7;const now=Date.now(),from=now-DAYS*DAY_MS;const recs=(appData.records||[]).filter(function(r){return r.startTime>=from;});if(recs.length<3)return 25;const full=recs.filter(function(r){return r.type==='full';}).length;const half=recs.filter(function(r){return r.type==='half';}).length;const done=full+half;const rate=recs.length?done/recs.length:0;const fullRatio=done?full/done:0;const intCount=recs.reduce(function(s,r){return s+((r.interruptions&&r.interruptions.length)||0);},0);const avgInt=recs.length?intCount/recs.length:0;if(rate>=0.8&&fullRatio>=0.8)return 50;if(rate<0.4||avgInt>=2||fullRatio<0.4)return 10;return 25;}
function getFatigueScore(){const now=Date.now(),from=now-2*3600000;const recs=(appData.records||[]).filter(function(r){return r.startTime>=from&&!isLogRecord(r);});if(recs.length<2)return 0;let score=0;const unfinished=recs.filter(function(r){return r.type==='incomplete';}).length;const ints=recs.reduce(function(s,r){return s+((r.interruptions&&r.interruptions.length)||0);},0);score+=(unfinished/recs.length)*60;score+=Math.min(1,ints/Math.max(1,recs.length*1.5))*40;return Math.min(100,Math.round(score));}
