function toggleOverviewJump(){overviewCalJumpOpen=!overviewCalJumpOpen;renderOverviewJump();}
function changeOverviewYear(delta){overviewCalYear+=Number(delta)||0;renderDiaryOverviewPage();}
function overviewJumpMonth(m){overviewCalMonth=Math.max(0,Math.min(11,(Number(m)||1)-1));overviewCalJumpOpen=false;renderDiaryOverviewPage();}
function changeOverviewMonth(delta){overviewCalMonth+=delta;if(overviewCalMonth<0){overviewCalMonth=11;overviewCalYear--;}else if(overviewCalMonth>11){overviewCalMonth=0;overviewCalYear++;}
renderDiaryOverviewPage();}
function goToDiaryDate(date){currentDiaryDate=date;switchLogTab('diary');}
function _cdSort(a,b){if(countdownSortMode==='added')return(Number(b.id)||0)-(Number(a.id)||0);const d=getDaysUntil(a.date)-getDaysUntil(b.date);return d!==0?d:String(a.title).localeCompare(String(b.title));}
function setCountdownSort(mode){countdownSortMode=mode==='added'?'added':'date';const sel=document.getElementById('cdSortSelect');if(sel&&sel.value!==countdownSortMode)sel.value=countdownSortMode;renderCountdowns();}
function _isPinned(c){return!!(c&&(c.pinned===1||c.pinned===true||c.pinned==='1'));}
function pinnedCountdowns(){const all=Array.isArray(appData.countdowns)?appData.countdowns:[];return all.filter(_isPinned);}
function renderCountdowns(){const list=document.getElementById('countdownList');if(!list)return;if(!appData.countdowns.length){list.innerHTML='<div style="text-align:center;color:#999;padding:40px;font-size:var(--fs-title);">还没有倒数日，点右上角添加</div>';return;}
const sorted=[...appData.countdowns].sort(_cdSort);list.innerHTML=sorted.map(c=>{const days=getDaysUntil(c.date);let color='var(--text-light)';if(days<=7)color='var(--danger)';else if(days<=30)color='var(--yellow-dark)';const isPin=_isPinned(c);const pinBtn='<button class="btn-small" onclick="event.stopPropagation();toggleCountdownPin('+
idArg(c.id)+')" title="'+
(isPin?'取消显示在计划页':'显示在计划页')+'" style="flex-shrink:0;background:'+
(isPin?'var(--primary)':'transparent')+';color:'+
(isPin?'var(--white)':'var(--text-light)')+';border:2px solid '+
(isPin?'var(--primary)':'var(--border)')+';padding:2px 8px;font-size:var(--fs-note);line-height:1.6;margin-right:var(--sp-6);">'+
(isPin?'📌 计划页':'📌')+'</button>';const noteHtml=c.note?'<div style="font-size:var(--fs-caption);color:var(--text-light);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+
escapeHtml(c.note)+'</div>':'';const borderLeft='';return('<div class="countdown-item" style="'+
borderLeft+'" onclick="openCountdownDetail('+
idArg(c.id)+')"><div style="font-size:34px;flex-shrink:0;width:40px;text-align:center;">'+
escapeHtml(c.icon||'📌')+'</div><div class="countdown-info" style="min-width:0;"><div class="countdown-title">'+
escapeHtml(c.title)+'</div><div class="countdown-date">'+
escapeHtml(c.date)+
(days>=0?' · 还剩':' · 已过')+
Math.abs(days)+'天</div>'+
noteHtml+'</div>'+
pinBtn+'<div class="countdown-days"><div class="num" style="color:'+
color+';">'+
(days>=0?days:Math.abs(days))+'</div><div class="unit">'+
(days>=0?'天后':'天前')+'</div></div></div>');}).join('');}
function toggleCountdownPin(id){const c=appData.countdowns.find(x=>idEq(x.id,id));if(!c)return;const isPin=_isPinned(c);c.pinned=isPin?0:1;saveData();renderCountdowns();renderPlanCountdowns();renderDiary();showToast(isPin?'已从计划页移除':'已显示在计划页');}
