function playSound(type){if(appData.settings.sound)return;if(appData.settings.sfxEnabled===false)return;const _t=typeof SFX_ALIAS==='object'&&SFX_ALIAS&&SFX_ALIAS[type]?SFX_ALIAS[type]:type;const now=Date.now();if(!SFX_IMPORTANT[_t]&&now-_sfxLastPlay<SFX_COOLDOWN_MS)return;_sfxLastPlay=now;const ctx=getSfxCtx();if(!ctx)return;let vol=Number(appData.settings.sfxVolume);if(!isFinite(vol))vol=0.3;vol=Math.max(0,Math.min(1,vol));if(vol<=0)return;try{const t0=ctx.currentTime;const tone=function(freq,dur,when,peak){const o=ctx.createOscillator();const g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(freq,when);o.connect(g);g.connect(ctx.destination);const p=peak||vol*0.4;g.gain.setValueAtTime(0,when);g.gain.linearRampToValueAtTime(p,when+0.008);g.gain.exponentialRampToValueAtTime(0.0001,when+dur);o.start(when);o.stop(when+dur+0.02);};if(_t==='start'){const o=ctx.createOscillator();const g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(220,t0);o.frequency.linearRampToValueAtTime(180,t0+0.18);o.connect(g);g.connect(ctx.destination);g.gain.setValueAtTime(0,t0);g.gain.linearRampToValueAtTime(vol*0.35,t0+0.01);g.gain.exponentialRampToValueAtTime(0.0001,t0+0.2);o.start(t0);o.stop(t0+0.22);}else if(_t==='finish'){tone(660,0.35,t0,vol*0.35);tone(880,0.3,t0+0.04,vol*0.3);tone(1320,0.2,t0+0.08,vol*0.18);}else if(_t==='reward'){tone(660,0.18,t0,vol*0.35);tone(880,0.22,t0+0.08,vol*0.3);}else if(_t==='error'){const o=ctx.createOscillator();const g=ctx.createGain();o.type='square';o.frequency.setValueAtTime(200,t0);o.frequency.linearRampToValueAtTime(100,t0+0.2);o.connect(g);g.connect(ctx.destination);g.gain.setValueAtTime(0,t0);g.gain.linearRampToValueAtTime(vol*0.18,t0+0.01);g.gain.exponentialRampToValueAtTime(0.0001,t0+0.22);o.start(t0);o.stop(t0+0.24);}else if(_t==='tap'){tone(1200,0.05,t0,vol*0.18);}else if(_t==='microStart'){tone(523,0.12,t0,vol*0.22);tone(698,0.14,t0+0.06,vol*0.2);}else if(_t==='microEnd'){tone(698,0.1,t0,vol*0.2);tone(523,0.14,t0+0.05,vol*0.18);}else if(_t==='breakStart'){tone(587,0.16,t0,vol*0.28);tone(440,0.24,t0+0.09,vol*0.24);}else if(_t==='taskDone'){tone(784,0.12,t0,vol*0.26);tone(988,0.14,t0+0.05,vol*0.24);tone(1319,0.18,t0+0.1,vol*0.2);}else if(_t==='habitDone'){tone(1046,0.1,t0,vol*0.24);tone(1568,0.14,t0+0.05,vol*0.16);}else if(_t==='completeFull'){tone(880,0.16,t0,vol*0.24);tone(1174,0.2,t0+0.06,vol*0.18);}else if(_t==='nearEnd'){tone(700,0.16,t0,vol*0.26);tone(700,0.16,t0+0.24,vol*0.26);}}catch(e){if(window.__silent)window.__silent(e,'01e:playSound');}}
const FOCUS_QUOTES_START=['🍅 此刻，你在这里。','深呼吸。开始就好。','专注是给自己最好的礼物。','时间会奖励坐下来的人。','放下手机，世界是你的。','你不需要更多时间，只需要这一段。','这一颗番茄，只属于眼前的事。','一个开始，就赢了一半。','静下来，慢就是快。','慢慢来，比较快。'];const FOCUS_QUOTES_FINISH=['🎉 你做到了。','又一颗番茄落地。','这一段专注，是你的。','好状态会越滚越大。','继续，节奏已经在了。','身体的疲惫会过去，今天的成果留下了。','你又一次选择了认真。','给明天的自己留个好开头。'];function showFocusQuote(kind){const arr=kind==='finish'?FOCUS_QUOTES_FINISH:FOCUS_QUOTES_START;const text=arr[Math.floor(Math.random()*arr.length)];const el=document.createElement('div');el.className='focus-quote';el.textContent=text;document.body.appendChild(el);setTimeout(function(){if(el.parentNode)el.parentNode.removeChild(el);},3800);}
