function habitStatsLine(h,today){const hs=habitStats(h,appData.habitLogs[h.id]||[],today,HABIT_WINDOW_DAYS);return'🔥 连续 '+hs.cur+' 天 · 达标 '+Math.round(hs.rate*100)+'%';}
function habitStageBadge(h){const stage=getHabitStage(h.growthPoints||0);return'<span class="habit-stage-badge" title="成长值 '+(h.growthPoints||0)+'">'+escapeHtml(stage.name)+'</span>';}
function _habitRowHtml(h,today,draggable){const checked=(appData.habitLogs[h.id]||[]).includes(today);const _cbHtml='<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect class="cb-shape" x="2.5" y="2.5" width="19" height="19" rx="6"/><polyline class="cb-check" points="6,12 10.5,16.5 18,8"/></svg>';const _noteHtml=h.note?'<div class="habit-note">'+escapeHtml(h.note)+'</div>':'';return'<div class="habit-item" data-id="'+h.id+'" draggable="'+(draggable?'true':'false')+'" title="'+(draggable?'可拖拽排序':'')+'">'+'<div class="habit-checkbox '+(checked?'checked':'')+'" onclick="toggleHabit('+idArg(h.id)+')">'+_cbHtml+'</div>'+'<div class="habit-info"><div class="habit-title-row"><span class="habit-name">'+escapeHtml(h.name)+'</span>'+habitStageBadge(h)+'</div>'+'<div class="habit-streak">'+habitStatsLine(h,today)+'</div>'+_noteHtml+
habitHeatmapHtml(h,HABIT_WINDOW_DAYS)+'</div>'+
(h.archived?'':'<span class="habit-move" '+(draggable?'':'style="display:none"')+'><button class="btn-small move-btn" onclick="event.stopPropagation();moveHabit('+idArg(h.id)+',-1)" title="上移">↑</button><button class="btn-small move-btn" onclick="event.stopPropagation();moveHabit('+idArg(h.id)+',1)" title="下移">↓</button></span>')+'<div class="habit-arrow" onclick="openHabitDetail('+idArg(h.id)+')">›</div></div>';}
const HABIT_CAT_COLORS=[{fg:'#4F46E5',bg:'#EEF2FF'},{fg:'#059669',bg:'#ECFDF5'},{fg:'#EA580C',bg:'#FFF7ED'},{fg:'#DB2777',bg:'#FDF2F8'},{fg:'#0284C7',bg:'#F0F9FF'},{fg:'#7C3AED',bg:'#F5F3FF'},{fg:'#0D9488',bg:'#F0FDFA'},{fg:'#E11D48',bg:'#FFF1F2'}];function habitCatColor(cat){const s=String(cat&&cat.id?cat.id:(cat&&cat.name)||'');let h=0;for(let i=0;i<s.length;i++)h=(h*31+s.charCodeAt(i))>>>0;return HABIT_CAT_COLORS[h%HABIT_CAT_COLORS.length];}
function renderHabits(){const list=document.getElementById('habitList');const today=getTodayStr();const all=appData.habits||[];const sorter=sortHabits;const active=sorter(all.filter(function(h){return!h.archived;}));const archived=sorter(all.filter(function(h){return!!h.archived;}));if(!all.length){list.innerHTML='<div class="empty-state"><span class="empty-icon">🌱</span><div class="empty-title">还没有习惯</div><div class="empty-desc">每天打卡，让好习惯慢慢长成大树</div></div>';return;}
const sortBy=getSortPrefs().habits.by;const draggable=sortBy==='manual';const cats=normHabitCats(appData.habitCats);const rowOf=function(h){return _habitRowHtml(h,today,draggable);};let html;if(!cats.length){html=active.map(rowOf).join('');if(!active.length)html='<div class="review-empty">习惯都归档了，可在归档区恢复</div>';}else{const open=appData.habitCatOpen||{};const checkedToday=function(h){return(appData.habitLogs[h.id]||[]).indexOf(today)>=0;};html=(habitCatGroups(active,cats)).map(function(grp){if(grp.id===''){if(!grp.items.length)return'';return('<div class="habit-folder-head habit-folder-head--plain" style="--cat:var(--text-light);--cat-soft:var(--surface-2)">'+'<span class="folder-chip">·</span>'+'<span class="folder-name">未分类</span>'+'<span class="folder-today">'+grp.items.length+'</span>'+'</div>'+'<div class="habit-folder-body">'+grp.items.map(rowOf).join('')+'</div>');}
const opened=!!open[grp.id];const c=habitCatColor(grp);const mono=escapeHtml(Array.from(grp.name||'?')[0]||'?');const done=grp.items.filter(checkedToday).length;const style='--cat:'+c.fg+';--cat-soft:'+c.bg;return('<div class="habit-folder-head'+(opened?' open':'')+'" style="'+style+'" onclick="toggleHabitCat('+idArg(grp.id)+')">'+'<span class="folder-chip">'+mono+'</span>'+'<span class="folder-name">'+escapeHtml(grp.name)+'</span>'+'<span class="folder-today'+(done>0&&done===grp.items.length?' all':'')+'" title="今日已完成 '+done+'/'+grp.items.length+'">'+done+'/'+grp.items.length+'</span>'+'<svg class="folder-caret" viewBox="0 0 24 24" aria-hidden="true"><path d="M9 6l6 6-6 6"/></svg>'+'<span class="folder-del" onclick="event.stopPropagation();deleteHabitCat('+idArg(grp.id)+')" title="删除分类（习惯退回未分类）">✕</span>'+'</div>'+
(opened?'<div class="habit-folder-body" style="'+style+'">'+grp.items.map(rowOf).join('')+'</div>':''));}).join('');if(!html)html='<div class="review-empty">习惯都归档了，可在归档区恢复</div>';}
if(archived.length){html+='<div class="habit-archive-h">已归档（'+archived.length+'）</div>';html+=archived.map(function(h){return _habitRowHtml(h,today,false);}).join('');}
list.innerHTML=html;}
function toggleHabitCat(catId){if(!appData.habitCatOpen||typeof appData.habitCatOpen!=='object')appData.habitCatOpen={};const k=String(catId);appData.habitCatOpen[k]=!appData.habitCatOpen[k];saveData();renderHabits();}
function addHabitCat(){const _applyCat=function(raw){const name=normHabitCatName(raw);if(!name)return;if(!Array.isArray(appData.habitCats))appData.habitCats=[];let hit=appData.habitCats.find(function(c){return c&&c.name===name;});if(!hit){hit={id:'hc'+Date.now().toString(36)+Math.floor(Math.random()*1000),name:name};appData.habitCats.push(hit);appData.habitCatOpen[hit.id]=true;}
saveData();renderHabits();};if(typeof window.rsPrompt==='function'){window.rsPrompt('给这个分类起个名字：',{title:'新建习惯分类',placeholder:'例如：学习 / 运动 / 生活',okText:'创建'}).then(_applyCat);}else{_applyCat(prompt('新分类名：'));}}
function deleteHabitCat(catId){const cs=appData.habitCats||[];const hit=cs.find(function(c){return c&&idEq(c.id,catId);});if(!hit)return;const n=(appData.habits||[]).filter(function(h){return h&&idEq(h.catId,catId);}).length;const msg='删除分类「'+hit.name+'」？\n'+(n?n+' 个习惯会退回「未分类」，不会被删。':'（里面没有习惯）');const run=function(){appData.habits.forEach(function(h){if(h&&idEq(h.catId,catId))h.catId=null;});appData.habitCats=cs.filter(function(c){return!(c&&idEq(c.id,catId));});if(appData.habitCatOpen)delete appData.habitCatOpen[String(catId)];saveData();renderHabits();};if(typeof window.rsConfirm==='function')window.rsConfirm(msg).then(function(ok){if(ok)run();});else if(window.confirm(msg))run();}
function openHabitDetail(id){const h=appData.habits.find(x=>idEq(x.id,id));if(!h)return;const logs=(appData.habitLogs[id]||[]).sort().reverse();const today=getTodayStr();const hs=habitStats(h,appData.habitLogs[id]||[],today,HABIT_WINDOW_DAYS);const freqOpts=[1,2,3,4,5,6,7].map(function(n){return'<option value="'+n+'"'+(habitFreqPerWeek(h)===n?' selected':'')+'>'+(n>=7?'每天':'每周 '+n+' 次')+'</option>';}).join('');const _stage=getHabitStage(h.growthPoints||0);document.getElementById('habitDetailTitle').textContent='🌱 '+h.name;document.getElementById('habitDetailBody').innerHTML=`<div class="settings-group" style="margin-bottom:var(--sp-12);"><h3>习惯信息</h3>`
+`<div class="habit-stat-grid">`
+`<div><b>${hs.cur}</b><span>当前连续</span></div>`
+`<div><b>${hs.best}</b><span>历史最长</span></div>`
+`<div><b>${Math.round(hs.rate * 100)}%</b><span>近${HABIT_WINDOW_DAYS}天达标</span></div>`
+`<div><b>${_stage.emoji}${h.growthPoints || 0}</b><span>成长点</span></div>`
+`</div>`
+habitHeatmapHtml(h,HABIT_WINDOW_DAYS)
+`<div class="setting-row"><div class="setting-label">目标频次</div><select class="setting-input" id="habitDetailFreq" onchange="saveHabitFreq(${idArg(id)})" style="flex:1;">${freqOpts}</select></div>`
+`<div class="setting-row"><div class="setting-label">分类</div><select class="setting-input" id="habitDetailCat" onchange="saveHabitCat(${idArg(id)})" style="flex:1;">${(function () {
        const cur = habitCatOf(h);
        const opts = ['<option value=""' + (cur === HABIT_CAT_UNGROUPED ? ' selected' : '') + '>未分类</option>'];
        (normHabitCats(appData.habitCats) || []).forEach(function (c) {
          opts.push('<option value="' + escapeHtml(String(c.id)) + '"' + (String(c.id) === cur ? ' selected' : '') + '>📁 ' + escapeHtml(c.name) + '</option>');
        });
        return opts.join('');
      })()}</select></div>`
+`<div class="setting-row"><div class="setting-label">名称</div><input type="text" class="setting-input" id="habitDetailName" value="${escapeHtml(h.name)}" style="flex:1;"></div><div class="setting-row"><div class="setting-label">备注</div></div><textarea id="habitDetailNote" style="width:100%;padding:var(--sp-8);border:2px solid var(--border);border-radius:var(--radius-sm);min-height:60px;font-family:inherit;">${escapeHtml(h.note || '')}</textarea><div class="modal-buttons" style="margin-top:var(--sp-10)"><button class="modal-btn primary" onclick="saveHabitDetail(${idArg(id)})">保存</button></div><div class="modal-buttons" style="margin-top:var(--sp-8)"><button class="modal-btn secondary" onclick="toggleHabitArchive(${idArg(id)})">${h.archived ? '♻️ 恢复习惯' : '📦 归档习惯'}</button><button class="modal-btn danger" onclick="deleteHabit(${idArg(id)})">删除习惯</button></div></div><div class="settings-group"><h3>补打卡</h3><div style="display:flex;gap:var(--sp-8);align-items:center;margin-bottom:var(--sp-10);"><input type="date" id="habitBackfillDate" value="${getTodayStr()}" max="${getTodayStr()}" style="flex:1;padding:var(--sp-8);border:2px solid var(--border);border-radius:var(--radius-sm);font-size:var(--fs-title);"><button class="modal-btn green" style="flex:0 0 auto" onclick="backfillHabit(${idArg(id)})">补打卡</button></div><div style="font-size:var(--fs-title);color:var(--text-light);margin-bottom:var(--sp-8);">选择日期后点击补打卡，可补打历史日期；不能打卡未来日期</div><h3 style="margin-top:var(--sp-12);">历史打卡（${logs.length}天，点击可取消）</h3>${logs.length ? logs.map(d => `<div class="harvest-item"style="cursor:pointer;"onclick="toggleHabit(${idArg(id)},'${d}');openHabitDetail(${idArg(id)})">${d}✓</div>`).join('') : '<div style="text-align:center;color:#999;padding:var(--sp-16);">暂无记录</div>'}</div>`;showModal('habitDetailModal');}
function backfillHabit(id){const dateStr=document.getElementById('habitBackfillDate').value;if(!dateStr){showToast('请选择日期');return;}
toggleHabit(id,dateStr);openHabitDetail(id);}
function saveHabitDetail(id){const h=appData.habits.find(x=>idEq(x.id,id));if(h){h.name=document.getElementById('habitDetailName').value.trim()||h.name;h.note=document.getElementById('habitDetailNote').value.trim();saveData();renderHabits();showToast('已保存');}}
function saveHabitCat(id){const h=appData.habits.find(x=>idEq(x.id,id));const el=document.getElementById('habitDetailCat');if(!h||!el)return;h.catId=el.value?el.value:null;saveData();renderHabits();showToast(h.catId?'已移入分类':'已移出分类');}
