function toggleHabitArchive(id){const h=appData.habits.find(x=>idEq(x.id,id));if(!h)return;h.archived=!h.archived;saveData();renderHabits();closeModal('habitDetailModal');showToast(h.archived?'已归档：'+h.name:'已恢复：'+h.name);}
