function onUp(e){if(!dragging)return;dragging=false;box.classList.remove('dragging');if(moved){let prect=box.parentNode.getBoundingClientRect();let rect=box.getBoundingClientRect();appData.tree.timerTreePos={x:rect.left-prect.left,y:rect.top-prect.top};saveData();}else{timerTreeTalk();}}
