function buildWheelSVG(rewards){const cx=120,cy=120,r=118;const total=rewards.reduce(function(s,rw){return s+rw.w;},0);let html='<svg viewBox="0 0 240 240" width="240" height="240">';let cum=0;rewards.forEach(function(rw){const span=(rw.w/total)*360;const start=cum;const end=cum+span;const sRad=((start-90)*Math.PI)/180;const eRad=((end-90)*Math.PI)/180;const x1=cx+r*Math.cos(sRad),y1=cy+r*Math.sin(sRad);const x2=cx+r*Math.cos(eRad),y2=cy+r*Math.sin(eRad);const large=span>180?1:0;html+='<path d="M'+
cx+','+
cy+' L'+
x1.toFixed(1)+','+
y1.toFixed(1)+' A'+
r+','+
r+' 0 '+
large+' 1 '+
x2.toFixed(1)+','+
y2.toFixed(1)+' Z" fill="'+
rw.color+'" stroke="#fff" stroke-width="2"/>';cum=end;});html+='<circle cx="'+cx+'" cy="'+cy+'" r="22" fill="#fff" stroke="#FF6B4A" stroke-width="3"/>';html+='<text x="'+cx+'" y="'+cy+'" text-anchor="middle" dominant-baseline="central" font-size="16">🎁</text>';html+='</svg>';return html;}
