function renderTeamSystem(){let ts=appData.teamSystem;if(!ts){ts=createDefaultAppData().teamSystem;appData.teamSystem=ts;}
if(!ts.today)
ts.today={date:null,startCode:null,partnerJoined:false,myEndCode:null,myCompleted:null,partnerEndCode:null,partnerCompleted:null,settled:false,settlementResult:null};if(!ts.history)ts.history=[];let today=getTodayStr();let todayActive=ts.today.date===today;if(!todayActive&&ts.today.date&&!ts.today.settled){settleTeamTask();}
if(!todayActive){ts.today={date:today,startCode:null,partnerJoined:false,myEndCode:null,myCompleted:null,partnerEndCode:null,partnerCompleted:null,settled:false,settlementResult:null};todayActive=true;}
let badge=document.getElementById('teamStarBadge');if(badge)badge.textContent=ts.stars+' ⭐';let content=document.getElementById('teamContent');if(!content)return;let settled=ts.today.settled;let myCompleted=getMyTaskCompletedStatus();let html='';let todayFull=getTodayEffectiveFull();let rs=appData.rankSystem;let target=rs.dailyTask&&rs.dailyTask.date===today?rs.dailyTask.target||3:3;html+=buildTeamRulesHTML();html+=buildTeamStatusHTML(ts,settled,myCompleted,todayFull,target);html+=buildTeamRankHTML(ts,settled);html+=buildTeamSprintHTML(ts,today);if(settled){html+=buildTeamSettledHTML(ts,today,myCompleted);}else{html+=buildTeamActHTML(ts,today,todayFull,target,myCompleted);}
content.innerHTML=html;renderTeamHistory();}
function toggleTeamSection(){let body=document.getElementById('teamBody');let arrow=document.getElementById('teamSectionArrow');if(!body)return;if(body.style.display==='none'){body.style.display='block';if(arrow)arrow.textContent='▾';renderTeamSystem();}else{body.style.display='none';if(arrow)arrow.textContent='▸';}}
function clearPartnerEndCode(){let ts=appData.teamSystem;if(ts.today){ts.today.partnerEndCode=null;ts.today.partnerCompleted=null;saveData();renderTeamSystem();}}
function copyTeamCode(code){if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(code).then(function(){showToast('已复制到剪贴板');}).catch(function(){fallbackCopy(code);});}else{fallbackCopy(code);}}
function fallbackCopy(code){let ta=document.createElement('textarea');ta.value=code;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();try{document.execCommand('copy');showToast('已复制到剪贴板');}catch(e){showToast('复制失败，请手动复制');}
document.body.removeChild(ta);}
function toggleTeamHistory(){let el=document.getElementById('teamHistoryList');let toggle=document.getElementById('teamHistoryToggle');if(!el)return;if(el.style.display==='none'){el.style.display='block';toggle.textContent='📋 收起组队历史';renderTeamHistory();}else{el.style.display='none';toggle.textContent='📋 查看组队历史';}}
function renderTeamHistory(){let el=document.getElementById('teamHistoryList');if(!el)return;let ts=appData.teamSystem;if(!ts.history||!ts.history.length){el.innerHTML='<div style="text-align:center;color:var(--text-light);padding:var(--sp-12);font-size:var(--fs-title);">暂无组队历史</div>';return;}
el.innerHTML=ts.history.map(function(h){let resultText='';let color='';let sc=h.starChange||0;let scText=(sc>0?'+'+sc:sc<0?''+sc:'±0')+'⭐';if(h.result==='win'){resultText='🎉 双方完成 '+scText;color='var(--green)';}else if(h.result==='neutral'){resultText='✅ 你完成了 '+scText;color='var(--yellow-dark)';}else{resultText='💔 '+scText;color='var(--danger)';}
let myText=h.myCompleted?'✅':'❌';let partnerText=h.partnerCompleted?'✅':'❌';return('<div class="team-history-item"><div><span class="team-history-date">'+
h.date+'</span> <span style="font-size:var(--fs-title);color:var(--text-light);">我'+
myText+' 队友'+
partnerText+'</span></div><span class="team-history-result" style="color:'+
color+';">'+
resultText+'</span></div>');}).join('');}
