if(typeof obj.series!=='string'||!obj.series.trim())
errors.push('缺少必填字段：series（剧情系列名，如 "深海谜城"）');const role=obj.role;if(!role||typeof role!=='object'){errors.push('缺少必填字段：role（角色卡对象）');}else{['name','title','avatar','intro'].forEach(function(k){if(typeof role[k]!=='string'||!role[k].trim())errors.push('role 缺少必填字段：'+k);});if(role.stats&&typeof role.stats==='object'){Object.keys(role.stats).forEach(function(k){if(typeof role.stats[k]!=='number')errors.push('role.stats.'+k+' 必须是数字');});}}
