function toggleImportedScripts(){_importedScriptsOpen=!_importedScriptsOpen;renderImportedScriptsBox();}
let _imScriptPanelOpen=false;function toggleImportedScriptPanel(){_imScriptPanelOpen=!_imScriptPanelOpen;const panel=document.getElementById('imScriptPanel');const arrow=document.getElementById('imScriptHeadArrow');if(panel)panel.style.display=_imScriptPanelOpen?'flex':'none';if(arrow)arrow.style.transform=_imScriptPanelOpen?'rotate(90deg)':'';try{renderImportedScriptsBox();renderImmersiveSettingsNote();}catch(e){if(window.__silent)window.__silent(e,'01f:toggleImportedScriptPanel');}}
