function removeImportedScriptUI(id){var _doRemove=function(){removeImportedScript(id);renderImportedScriptsBox();renderImmersiveSettingsNote();showToast('🗑️ 已删除副本');};var _msg='删除该剧情副本？\n（不影响你的任何数据，随时可重新导入）';if(typeof window.rsAsk==='function')window.rsAsk(_msg,{title:'删除副本',okText:'删除',danger:true},_doRemove);else if(confirm(_msg))_doRemove();}
